import{_ as a,o,c as r,a2 as i}from"./chunks/framework.DZhUhjDB.js";const g=JSON.parse('{"title":"07 — Ética y leyes: lo que todo profesional debe saber","description":"","frontmatter":{"title":"07 — Ética y leyes: lo que todo profesional debe saber"},"headers":[],"relativePath":"modules/fundamentos/07-etica-y-leyes.md","filePath":"modules/fundamentos/07-etica-y-leyes.md","lastUpdated":1787330151000}'),t={name:"modules/fundamentos/07-etica-y-leyes.md"};function s(l,e,n,c,d,u){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="_07-—-etica-y-leyes-lo-que-todo-profesional-debe-saber" tabindex="-1">07 — Ética y leyes: lo que todo profesional debe saber <a class="header-anchor" href="#_07-—-etica-y-leyes-lo-que-todo-profesional-debe-saber" aria-label="Permalink to &quot;07 — Ética y leyes: lo que todo profesional debe saber&quot;">​</a></h1><blockquote><p>🎯 <strong>Objetivo:</strong> que entiendas la línea entre investigación legítima y delito, y por qué la ética no es opcional.</p></blockquote><h2 id="_1-la-regla-de-oro-del-hacking-etico" tabindex="-1">1. La regla de oro del hacking ético <a class="header-anchor" href="#_1-la-regla-de-oro-del-hacking-etico" aria-label="Permalink to &quot;1. La regla de oro del hacking ético&quot;">​</a></h2><blockquote><p><strong>Si no tienes permiso por escrito, no lo hagas.</strong></p></blockquote><p>No importa que la vulnerabilidad sea obvia. No importa que la empresa sea negligente. No importa que tu intención sea ayudar. <strong>Sin autorización, es delito</strong> en casi todas las jurisdicciones.</p><h2 id="_2-por-que-existe-el-hacking-etico" tabindex="-1">2. Por qué existe el hacking ético <a class="header-anchor" href="#_2-por-que-existe-el-hacking-etico" aria-label="Permalink to &quot;2. Por qué existe el hacking ético&quot;">​</a></h2><p>Porque las empresas necesitan a gente que piense como el atacante para encontrar huecos <strong>antes</strong> de que los exploten. Pero necesitan garantías legales: si el &quot;hacker bueno&quot; hace algo sin permiso y causa daño real, ¿quién responde?</p><p>Por eso existe:</p><ul><li><strong>Contrato / scope</strong> — autorizar exactamente qué puedes probar.</li><li><strong>Reglas de engagement</strong> — qué métodos están permitidos, cuáles no (¿DoS? ¿ingeniería social? ¿datos reales?).</li><li><strong>Disclosure coordinado</strong> — aviso al fabricante antes de publicar.</li><li><strong>NDA</strong> — no divulgar lo que veas.</li></ul><h2 id="_3-divulgacion-responsable-coordinated-disclosure" tabindex="-1">3. Divulgación responsable (Coordinated Disclosure) <a class="header-anchor" href="#_3-divulgacion-responsable-coordinated-disclosure" aria-label="Permalink to &quot;3. Divulgación responsable (Coordinated Disclosure)&quot;">​</a></h2><p>El ciclo correcto cuando encuentras algo:</p><ol><li><strong>Reportas</strong> al fabricante (o a través de un bug bounty) con detalle técnico suficiente para reproducir.</li><li><strong>Esperas</strong> un plazo razonable (típico: 90 días) a que parchear.</li><li><strong>Si parchean</strong>, publicas los detalles reconociendo al fabricante.</li><li><strong>Si no parchean</strong> y el riesgo es alto, publiques con aviso y un plazo mayor.</li></ol><p><strong>NO:</strong></p><ul><li>❌ Vender un 0-day en mercados negros (sí, existen, pero no es profesional).</li><li>❌ Exigir rescate (&quot;te digo el bug si me pagas&quot;).</li><li>❌ Amenazar con publicarlo.</li><li>❌ Probar el bug en sistemas reales sin autorización.</li></ul><h2 id="_4-lo-que-si-puedes-hacer-sin-pedir-permiso" tabindex="-1">4. Lo que SÍ puedes hacer sin pedir permiso <a class="header-anchor" href="#_4-lo-que-si-puedes-hacer-sin-pedir-permiso" aria-label="Permalink to &quot;4. Lo que SÍ puedes hacer sin pedir permiso&quot;">​</a></h2><ul><li>Auditar tu propio equipo o tu propio código.</li><li>Hacer cosas en <strong>laboratorios aislados</strong> (HackTheBox, TryHackMe, Docker labs propios).</li><li>Analizar código <strong>open source</strong> que ya está publicado.</li><li>Leer CVE/Changelog público y estudiarlos.</li><li>Participar en <strong>CTFs</strong> (Capture The Flag) expresamente diseñados para practicar.</li></ul><h2 id="_5-marco-legal-segun-pais-resumen-general" tabindex="-1">5. Marco legal según país (resumen general) <a class="header-anchor" href="#_5-marco-legal-segun-pais-resumen-general" aria-label="Permalink to &quot;5. Marco legal según país (resumen general)&quot;">​</a></h2><blockquote><p>⚠️ No soy abogado. Esto es solo un resumen cultural — verifica siempre la ley local.</p></blockquote><h3 id="espana-🇪🇸" tabindex="-1">España 🇪🇸 <a class="header-anchor" href="#espana-🇪🇸" aria-label="Permalink to &quot;España 🇪🇸&quot;">​</a></h3><ul><li><strong>Código Penal</strong> art. 197 (acceso no autorizado a datos), 264 (daño informático), 264 bis (sabotaje).</li><li>Ley de Protección de Datos (LOPD-GDD) y RGPD europeo.</li><li>Es delito incluso acceder sin causar daño visible.</li></ul><h3 id="mexico-🇲🇽" tabindex="-1">México 🇲🇽 <a class="header-anchor" href="#mexico-🇲🇽" aria-label="Permalink to &quot;México 🇲🇽&quot;">​</a></h3><ul><li><strong>Código Penal Federal</strong> art. 211 bis 1-4 (delitos informáticos).</li><li>Ley Federal de Protección de Datos Personales.</li></ul><h3 id="argentina-🇦🇷" tabindex="-1">Argentina 🇦🇷 <a class="header-anchor" href="#argentina-🇦🇷" aria-label="Permalink to &quot;Argentina 🇦🇷&quot;">​</a></h3><ul><li><strong>Código Penal</strong> art. 153-157 (delitos信息技术).</li><li>Ley 25.326 de Protección de Datos.</li></ul><h3 id="colombia-🇨🇴" tabindex="-1">Colombia 🇨🇴 <a class="header-anchor" href="#colombia-🇨🇴" aria-label="Permalink to &quot;Colombia 🇨🇴&quot;">​</a></h3><ul><li>Ley 1273 de 2009 (delitos informáticos).</li></ul><h3 id="chile-🇨🇱" tabindex="-1">Chile 🇨🇱 <a class="header-anchor" href="#chile-🇨🇱" aria-label="Permalink to &quot;Chile 🇨🇱&quot;">​</a></h3><ul><li>Ley 19.223 (delitosinformáticos).</li></ul><h3 id="ee-uu-🇺🇸" tabindex="-1">EE.UU. 🇺🇸 <a class="header-anchor" href="#ee-uu-🇺🇸" aria-label="Permalink to &quot;EE.UU. 🇺🇸&quot;">​</a></h3><ul><li><strong>CFAA</strong> (Computer Fraud and Abuse Act) — muy agresivo, multas fuertes.</li><li><strong>DMCA</strong> — tiene excepciones de seguridad research eludiendo DRM.</li><li>Algunos estados tienen leyes adicionales.</li></ul><blockquote><p>📂 Documentos marco y compliance en <a href="./../02-SEGURIDAD-INFORMACION/06-compliance-normativas/"><code>02-SEGURIDAD-INFORMACION/06-compliance-normativas/</code></a>.</p></blockquote><h2 id="_6-el-que-no-hacer-en-tu-trabajo" tabindex="-1">6. El &quot;qué NO hacer&quot; en tu trabajo <a class="header-anchor" href="#_6-el-que-no-hacer-en-tu-trabajo" aria-label="Permalink to &quot;6. El &quot;qué NO hacer&quot; en tu trabajo&quot;">​</a></h2><ul><li>🔒 No uses accesos obtenidos en pruebas para beneficio propio.</li><li>🔒 No reveles vulnerabilidades públicamente sin avisar al fabricante primero.</li><li>🔒 No pruebes DoS en producción sin autorización explícita (puede tumbar negocio real).</li><li>🔒 No hagas pruebas de ingeniería social si no están en el scope escrito.</li><li>🔒 No borres logs (a menos que sea parte autorizada de un test).</li><li>🔒 No mientas sobre lo que hiciste — la trazabilidad es tu mejor defensa.</li></ul><h2 id="_7-el-que-si-hacer-en-tu-trabajo" tabindex="-1">7. El &quot;qué SÍ hacer&quot; en tu trabajo <a class="header-anchor" href="#_7-el-que-si-hacer-en-tu-trabajo" aria-label="Permalink to &quot;7. El &quot;qué SÍ hacer&quot; en tu trabajo&quot;">​</a></h2><ul><li>✍️ <strong>Documenta TODO.</strong> Tu trabajo sin evidencia no vale.</li><li>🤝 <strong>Comunica hallazgo crítico</strong> al CISO y al equipo afectado rápido.</li><li>🧪 <strong>Prueba en sandbox primero</strong> todo lo que pueda romper.</li><li>📜 <strong>Mantén contrato firmado</strong> y guárdalo años.</li><li>🗑️ <strong>Borra datos sensibles</strong> que recopiles en pruebas una vez terminado.</li><li>👥 <strong>Respeta a otros equipos</strong> — un pentester arrogante no dura.</li></ul><h2 id="_8-privacidad-gdpr-rgpd-lopd" tabindex="-1">8. Privacidad: GDPR / RGPD / LOPD <a class="header-anchor" href="#_8-privacidad-gdpr-rgpd-lopd" aria-label="Permalink to &quot;8. Privacidad: GDPR / RGPD / LOPD&quot;">​</a></h2><p>Si manejas datos personales, aplica todo esto:</p><ul><li><strong>Minimización</strong>: recopila lo mínimo necesario.</li><li><strong>Propósito claro</strong>: define para qué los usas antes de pedirlos.</li><li><strong>Consentimiento informado</strong>: explica qué harás y obtén permiso.</li><li><strong>Retención limitada</strong>: borra cuando ya no los necesites.</li><li><strong>Transparencia</strong>: ten un registro de actividades de tratamiento.</li><li><strong>Notificación de brecha</strong>: si hay fuga, notifica a la autoridad en 72h (en la UE).</li></ul><h2 id="_9-cuando-algo-sale-mal-—-que-hacer" tabindex="-1">9. Cuando algo sale mal — qué hacer <a class="header-anchor" href="#_9-cuando-algo-sale-mal-—-que-hacer" aria-label="Permalink to &quot;9. Cuando algo sale mal — qué hacer&quot;">​</a></h2><p>Si en una prueba autorizada rompes algo:</p><ol><li><strong>Para inmediatamente</strong> y documenta lo que pasó.</li><li><strong>Avisa al cliente</strong> sin maquillar.</li><li><strong>Trabaja con el equipo técnico</strong> para resolver.</li><li><strong>Documenta la lección aprendida</strong> en un postmortem.</li><li><strong>Mejora tu proceso</strong> para que no vuelva a pasar.</li></ol><blockquote><p>La honestidad en este momento define tu carrera más que cualquier certificación.</p></blockquote><h2 id="_10-recursos-recomendados" tabindex="-1">10. Recursos recomendados <a class="header-anchor" href="#_10-recursos-recomendados" aria-label="Permalink to &quot;10. Recursos recomendados&quot;">​</a></h2><ul><li><strong>EC-Council Code of Ethics</strong></li><li><strong>(ISC)² Code of Ethics</strong></li><li><strong>SANS Institute</strong> — su ética es referencia</li><li><strong>OWASP Code of Ethics</strong></li><li><strong><a href="https://www.ccc.de/en/club/manifesto" target="_blank" rel="noreferrer">Chaos Computer Club manifesto</a></strong> si te interesa la postura europea</li></ul><h2 id="✏️-ejercicios-reflexiones" tabindex="-1">✏️ Ejercicios / reflexiones <a class="header-anchor" href="#✏️-ejercicios-reflexiones" aria-label="Permalink to &quot;✏️ Ejercicios / reflexiones&quot;">​</a></h2><ol><li><strong>Lee el contrato</strong> del último servicio que aceptaste sin leer (probablemente sea un banco o una app). Fíjate qué dice sobre tus datos.</li><li><strong>Pregúntate:</strong> si encontraras mañana una vulnerabilidad crítica en el banco donde tienes tu cuenta, ¿qué harías? Escribe el procedimiento en 5 pasos.</li><li><strong>Estudia un caso:</strong> busca &quot;vulnerabilidad reportada&quot; en las noticias. Mira cómo reaccionó la empresa. ¿Fue coordinada?</li><li><strong>Anota:</strong> redacta tu propio &quot;código de ética personal&quot; en 5 frases. Te servirá para el CV y para guiar tus decisiones.</li></ol><h2 id="📌-donde-profundizar" tabindex="-1">📌 Dónde profundizar <a class="header-anchor" href="#📌-donde-profundizar" aria-label="Permalink to &quot;📌 Dónde profundizar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Carpeta</th></tr></thead><tbody><tr><td>GRC / Compliance</td><td><a href="./../02-SEGURIDAD-INFORMACION/"><code>02-SEGURIDAD-INFORMACION/</code></a></td></tr><tr><td>CISO role</td><td><a href="./../02-SEGURIDAD-INFORMACION/ciso/"><code>02-SEGURIDAD-INFORMACION/ciso/</code></a></td></tr><tr><td>Privacy / DPO</td><td><a href="./../02-SEGURIDAD-INFORMACION/data-protection-officer/"><code>02-SEGURIDAD-INFORMACION/data-protection-officer/</code></a></td></tr><tr><td>Auditor</td><td><a href="./../02-SEGURIDAD-INFORMACION/auditor-seguridad/"><code>02-SEGURIDAD-INFORMACION/auditor-seguridad/</code></a></td></tr></tbody></table><blockquote><p>⏭️ <strong>Siguiente:</strong> <a href="./08-herramientas-esenciales"><code>08-herramientas-esenciales.md</code></a> — las herramientas más comunes que verás en tu día a día.</p></blockquote>',49)])])}const h=a(t,[["render",s]]);export{g as __pageData,h as default};
